144			[]Scope{{EncounterID: f.e2, Category: Diagnosis}}, f.start, f.end)
145		if err != nil {
146			t.Fatal(err)
147		}
148		// e2 下一条已生效诊断：被 authE2 覆盖，可用于构造“一条覆盖、一条未覆盖”的混合集合。
149		recE2, _ := f.s.CreateDraft(doc, f.pid, f.e2, Diagnosis, "二诊诊断内容")
150		if _, err := f.s.ActivateRecord(doc, recE2.ID); err != nil {
151			t.Fatal(err)
152		}
153		// 尚未开始的授权。
154		authFuture, err := f.s.Grant(doc, f.pid, rcv.ID,
155			[]Scope{{EncounterID: f.e1, Category: Diagnosis}}, f.clk.t.Add(time.Hour), f.clk.t.Add(2*time.Hour))
156		if err != nil {
157			t.Fatal(err)
158		}
159		// 已撤回的授权。
160		authRevoked, err := f.s.Grant(doc, f.pid, rcv.ID,
161			[]Scope{{EncounterID: f.e1, Category: Order}, {EncounterID: f.e1, Category: Diagnosis}}, f.start, f.end)
162		if err != nil {
163			t.Fatal(err)
164		}
165		if err := f.s.Revoke(doc, f.pid, authRevoked.ID); err != nil {
166			t.Fatal(err)
167		}
168	
169		auditBefore := len(mustAudit(t, f.s, f.pid))
170	
171		mustFail := func(name string, want error, actor Actor, pid ID, receiver string, authID ID, recs []ID, req string) {
172			t.Helper()
173			if _, err := f.s.CreateExchange(actor, pid, receiver, authID, recs, req); !errors.Is(err, want) {
174				t.Fatalf("%s: err = %v, want %v", name, err, want)
175			}
176		}
177	
178		mustFail("receiver actor", ErrAccessDenied, rcv, f.pid, rcv.ID, f.auth.ID, []ID{f.diag}, "r")
179		mustFail("empty record set", ErrInvalidArgument, doc, f.pid, rcv.ID, f.auth.ID, nil, "r")
180		mustFail("blank record id", ErrInvalidArgument, doc, f.pid, rcv.ID, f.auth.ID, []ID{"  "}, "r")
181		mustFail("blank request id", ErrInvalidArgument, doc, f.pid, rcv.ID, f.auth.ID, []ID{f.diag}, "  ")
182		mustFail("blank receiver", ErrInvalidArgument, doc, f.pid, " ", f.auth.ID, []ID{f.diag}, "r")
183		mustFail("blank auth", ErrInvalidArgument, doc, f.pid, rcv.ID, " ", []ID{f.diag}, "r")
184		mustFail("missing patient", ErrNotFound, doc, "pat_missing", rcv.ID, f.auth.ID, []ID{f.diag}, "r")
185		mustFail("missing auth", ErrNotFound, doc, f.pid, rcv.ID, "auth_missing", []ID{f.diag}, "r")
186		mustFail("auth of other patient", ErrMismatchedPatient, doc, other.ID, rcv.ID, f.auth.ID, []ID{f.diag}, "r")
187		mustFail("auth bound to other receiver", ErrInvalidArgument, doc, f.pid, rcv.ID, authB.ID, []ID{f.diag}, "r")
188		mustFail("missing record", ErrNotFound, doc, f.pid, rcv.ID, f.auth.ID, []ID{"rec_missing"}, "r")
189		mustFail("cross-patient record", ErrMismatchedPatient, doc, f.pid, rcv.ID, f.auth.ID, []ID{recOther.ID}, "r")
190		mustFail("draft record", ErrInvalidArgument, doc, f.pid, rcv.ID, f.auth.ID, []ID{f.draft}, "r")
191		mustFail("scope not covered", ErrAccessDenied, doc, f.pid, rcv.ID, authE2.ID, []ID{f.diag}, "r")
192		mustFail("future auth", ErrAccessDenied, doc, f.pid, rcv.ID, authFuture.ID, []ID{f.diag}, "r")
193		mustFail("revoked auth", ErrAccessDenied, doc, f.pid, rcv.ID, authRevoked.ID, []ID{f.diag}, "r")
194		// 混合集合：recE2 被 authE2 覆盖、diag 不被覆盖，整包拒绝。
195		mustFail("one uncovered record", ErrAccessDenied, doc, f.pid, rcv.ID, authE2.ID, []ID{f.diag, recE2.ID}, "r")
196	
197		// 已到期授权：推进时钟。
198		f.clk.t = f.end.Add(time.Minute)
199		mustFail("expired auth", ErrAccessDenied, doc, f.pid, rcv.ID, f.auth.ID, []ID{f.diag}, "r")
200		f.clk.t = f.start.Add(-2 * time.Hour)
201		mustFail("not started auth", ErrAccessDenied, doc, f.pid, rcv.ID, f.auth.ID, []ID{f.diag}, "r")
202		f.clk.t = f.start.Add(time.Hour)
203	
204		if got := len(mustAudit(t, f.s, f.pid)); got != auditBefore {
205			t.Fatalf("failed creates changed audit count: before=%d after=%d", auditBefore, got)
206		}
207		if xs, _ := f.s.ListExchanges(doc, f.pid); len(xs) != 0 {
208			t.Fatalf("failed creates persisted exchanges: %d", len(xs))
209		}
210	
211		// 患者停用后不能新建交换。
212		if err := f.s.DeactivatePatient(doc, f.pid); err != nil {
213			t.Fatal(err)
214		}
215		if _, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.diag}, "r"); !errors.Is(err, ErrDeactivated) {
216			t.Fatalf("deactivated create err = %v, want ErrDeactivated", err)
217		}
218	}
