func TestFetchedPackageDeliveryIsIsolated(t *testing.T) {
	f := setupExchange(t)
	x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.diag, f.ord}, "req-iso-fetch")
